async function buildWireframes() {
  const page = await pageAt(1);
  const sec = section(page, '03 — Low Fidelity Wireframes', 0, 0, 8000, 2000);
  clearSection(sec);
  const intro = F({ n: 'Intro 03', d: 'V', g: 8, w: 3000 }, [T('03 — Low Fidelity Wireframes', 'Display/XL'), T('Escala de grises, sin branding (logo como marcador), etiquetas reales de la ERS v1.1. Cada wireframe incluye a la derecha: nombre, rol autorizado, objetivo, elementos, acciones, estados y referencias a requerimientos. Los overlays (modales/toasts/paneles) muestran estados sobre la pantalla base.', 'Body/LG', 'text/secondary', { w: 3000 })]);
  sec.appendChild(intro); intro.x = 80; intro.y = 80;
  let count = 0;
  for (const [title, list] of wfSpecs()) {
    const built = [];
    for (const s of list) { const w = await safe('WF ' + s.id, async () => wscreen(s)); if (w) { built.push(w); count++; } }
    wplace(sec, built, title, 3);
  }
  fit(sec);
  // keep Design System section below the wireframes
  const ds = page.children.find(n => n.type === 'SECTION' && n.name === '04 — Design System');
  if (ds) { fit(ds); ds.x = 0; ds.y = sec.y + sec.height + 600; }
  return count;
}
